import styled from 'styled-components'
import { cores } from '../../styles'
import { Props } from './types/types'

export const TagContainer = styled.div<Props>`
  background-color: ${cores.rosa};
  color: ${cores.brancoSeco};
  font-size: ${(props) =>
    props.size === 'big' ? '16px' : '12px'}; /* Tamanho dinâmico */
  line-height: ${(props) =>
    props.size === 'big' ? '18px' : '14px'}; /* Altura dinâmica */
  text-align: center;
  font-weight: 700;
  padding: ${(props) =>
    props.size === 'big' ? '8px 16px' : '4px 8px'}; /* Padding dinâmico */
  display: inline-block; /* Para garantir que a tag não ocupe a largura total */
  border-radius: 4px;
  z-index: 2;
  max-height: 50px;
`
